// src/countries/countries.ts
var countries = countries_default;

// src/countries/country.utils.ts
function getCountryByCode(code) {
  const normalizedCode = code.trim().toUpperCase();
  return countries.find(
    (country) => country.code === normalizedCode
  );
}
function getCountryByAlpha3Code(code) {
  const normalizedCode = code.trim().toUpperCase();
  return countries.find(
    (country) => country.alpha3Code === normalizedCode
  );
}
function getCountryByNumericCode(code) {
  const normalizedCode = code.trim();
  return countries.find(
    (country) => country.numericCode === normalizedCode
  );
}
function searchCountries(query) {
  const normalizedQuery = query.trim().toLocaleLowerCase();
  if (!normalizedQuery) {
    return [];
  }
  return countries.filter((country) => {
    const searchFields = [
      country.names.common,
      country.names.official,
      country.code,
      country.alpha3Code,
      ...country.callingCodes ?? [],
      ...Array.isArray(country.currencyCode) ? country.currencyCode : [country.currencyCode]
    ];
    return searchFields.some(
      (value) => value != null && String(value).toLocaleLowerCase().includes(normalizedQuery)
    );
  });
}

